"""Pipeline stage implementations shared by the panel and the CLI.

Currently: generation of the dfnWorks driver script from case parameters.
"""

from __future__ import annotations

import json
from pathlib import Path

DRIVER_TEMPLATE = '''#!/usr/bin/env python3
"""dfnWorks meshing driver generated by the dfn-geos-workbench panel.

Case: {name!r}
Stages: dfnGen (fracture generation) -> LaGriT meshing -> UGE conversion.
Edit freely and re-run; the panel regenerates this file when parameters change.
"""
import os

# Optional solver executables (PFLOTRAN/FEHM/PETSc) are not needed for the
# generation+meshing workflow; keep the env entries defined but empty.
for _opt in ("PETSC_DIR", "PETSC_ARCH", "PFLOTRAN_EXE", "FEHM_EXE"):
    os.environ.setdefault(_opt, "")

from pydfnworks import DFNWORKS

jobname = os.path.join(os.path.dirname(os.path.abspath(__file__)), "output")

DFN = DFNWORKS(jobname, ncpu={ncpu}, dfnFlow_file="", dfnTrans_file="")

DFN.params["domainSize"]["value"] = {domain}
DFN.params["h"]["value"] = {h}
DFN.params["seed"]["value"] = {seed}
DFN.params["ignoreBoundaryFaces"]["value"] = {ignore_boundary_faces}
{extra_params}

{fracture_code}

DFN.make_working_directory(delete=True)
DFN.check_input()
DFN.print_domain_parameters()

DFN.create_network()
DFN.mesh_network(uniform_mesh={uniform_mesh})

DFN.lagrit2pflotran()
{dfm_code}
print("=== dfnWorks meshing complete ===")
'''


def _user_fractures(fractures: list[dict]) -> str:
    lines = []
    for f in fractures:
        extra = ""
        if f.get("aspect_ratio"):
            extra = f", aspect_ratio={f['aspect_ratio']}"
        lines.append(
            "DFN.add_user_fract(shape={shape!r}, radii={radii}{extra}, "
            "translation={translation}, normal_vector={normal}, "
            "permeability={permeability})".format(
                shape=f.get("shape", "rect"),
                radii=f.get("radii", 0.5),
                extra=extra,
                translation=f.get("translation", [0.0, 0.0, 0.0]),
                normal=f.get("normal", [0.0, 0.0, 1.0]),
                permeability=f.get("permeability", 1.0e-12)))
    return "\n".join(lines)


def _family_fractures(families: list[dict]) -> str:
    lines = []
    for fam in families:
        hy = fam.get("hy", {})
        lines.append(
            "DFN.add_fracture_family(shape={shape!r}, distribution={dist!r}, "
            "kappa={kappa}, probability={prob}, aspect={aspect}, "
            "beta_distribution=1, beta={beta}, trend={trend}, plunge={plunge}, "
            "{size_expr}, hy_variable='transmissivity', hy_function='correlated', "
            "hy_params={{'alpha': {alpha}, 'beta': {beta_h}}})".format(
                shape=fam.get("shape", "rect"),
                dist=fam.get("distribution", "constant"),
                kappa=fam.get("kappa", 20.0),
                prob=fam.get("probability", 1.0),
                aspect=fam.get("aspect", 1.0),
                beta=fam.get("beta", 0.0),
                trend=fam.get("trend", 0.0),
                plunge=fam.get("plunge", 90.0),
                size_expr=("constant=%s" % fam.get("constant", 2.0)
                           if fam.get("distribution", "constant") == "constant"
                           else "mean=%s, min=%s, max=%s" % (
                               fam.get("mean", 1.0), fam.get("min", 0.1),
                               fam.get("max", 5.0))),
                alpha=hy.get("alpha", 1e-13),
                beta_h=hy.get("beta", 1.0)))
    return "\n".join(lines)


def write_driver_script(case_dir: Path, case_name: str, params: dict) -> Path:
    """Render the dfnWorks driver script for a case and return its path."""
    params = params or {}
    domain = params.get("domain", [6.0, 6.0, 6.0])
    fractures = params.get("fractures", [])
    families = params.get("families", [])

    extra = ""
    if fractures:
        fracture_code = "# user-defined fractures\n" + _user_fractures(fractures)
    elif families:
        fracture_code = "# stochastic fracture families\n" + _family_fractures(families)
    else:
        # Default: two orthogonal constant-size fracture families (the layout
        # of the canonical examples/constant driver, proven end-to-end).
        # NOTE for user-defined fractures: dfnGen/FRAM rejects intersections
        # shorter than the mesh resolution h and fractures whose edges run
        # closer than h to another fracture's edge -- keep margins > h.
        fracture_code = "# stochastic fracture families (default)\n" + _family_fractures([
            {"distribution": "constant", "constant": 2.0, "aspect": 1.0,
             "kappa": 20.0, "probability": 1.0, "trend": 0.0, "plunge": 0.0},
            {"distribution": "constant", "constant": 2.0, "aspect": 1.0,
             "kappa": 20.0, "probability": 1.0, "trend": 35.0, "plunge": 90.0},
        ])
        extra += ("\nDFN.params['nPoly']['value'] = "
                  f"{int(params.get('n_poly', 24))}\n"
                  "DFN.params['stopCondition']['value'] = 0\n"
                  "DFN.params['orientationOption']['value'] = 1\n"
                  "DFN.params['boundaryFaces']['value'] = [1, 1, 0, 0, 0, 0]")

    include_dfm = bool(params.get("mesh_dfm", True))
    if params.get("boundary_faces"):
        extra += (f"\nDFN.params['boundaryFaces']['value'] = "
                  f"{params['boundary_faces']}")
    if params.get("n_poly"):
        extra += f"\nDFN.params['nPoly']['value'] = {int(params['n_poly'])}"
        extra += "\nDFN.params['stopCondition']['value'] = 0"
        extra += ("\nDFN.params['orientationOption']['value'] = "
                  f"{int(params.get('orientation_option', 1))}")

    code = DRIVER_TEMPLATE.format(
        name=case_name,
        ncpu=int(params.get("ncpu", 4)),
        domain=json.dumps(domain),
        h=params.get("h", 0.3),
        seed=int(params.get("seed", 42)),
        ignore_boundary_faces=int(bool(params.get("ignore_boundary_faces", True))),
        extra_params=extra,
        fracture_code=fracture_code,
        uniform_mesh="True",
        dfm_code=("\nDFN.mesh_dfm(allowed_percentage="
                  f"{float(params.get('dfm_allowed_percentage', 5))})"
                  if include_dfm else ""),
    )
    case_dir.mkdir(parents=True, exist_ok=True)
    driver = case_dir / "dfn_driver.py"
    driver.write_text(code)
    return driver
